<?php
require_once dirname(__DIR__).'/app/init.php';require_once dirname(__DIR__).'/app/layout.php';require_admin();$pdo=db();$errors=[];$statuses=['pending','confirmed','shipped','delivered','cancelled'];
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=(string)($_POST['action']??'');
 if($action==='add_product'){$ar=trim((string)($_POST['name_ar']??''));$fr=trim((string)($_POST['name_fr']??''));$da=trim((string)($_POST['desc_ar']??''));$df=trim((string)($_POST['desc_fr']??''));$price=filter_var($_POST['price']??null,FILTER_VALIDATE_FLOAT);$stock=filter_var($_POST['stock']??null,FILTER_VALIDATE_INT);$image=trim((string)($_POST['image']??''));$cat=filter_var($_POST['category']??null,FILTER_VALIDATE_INT);
 if($ar===''||$fr===''||mb_strlen($ar)>180||mb_strlen($fr)>180||$price===false||$price<=0||$price>999999999||$stock===false||$stock<0||$stock>1000000||($image!==''&&(!filter_var($image,FILTER_VALIDATE_URL)||!in_array(strtolower((string)parse_url($image,PHP_URL_SCHEME)),['http','https'],true)||mb_strlen($image)>1000)))$errors[]=t('error');
 else{$stmt=$pdo->prepare("INSERT INTO products(category_id,name_ar,name_fr,description_ar,description_fr,price,stock,image_url) VALUES(?,?,?,?,?,?,?,?)");$stmt->execute([$cat?:null,$ar,$fr,$da,$df,$price,$stock,$image?:null]);flash(t('save'));go('/admin.php#products');}}
 elseif($action==='archive'){$stmt=$pdo->prepare("UPDATE products SET is_active=0 WHERE id=?");$stmt->execute([filter_var($_POST['id']??0,FILTER_VALIDATE_INT)?:0]);flash(t('delete'));go('/admin.php#products');}
 elseif($action==='status'){$status=(string)($_POST['status']??'');if(in_array($status,$statuses,true)){$stmt=$pdo->prepare("UPDATE orders SET status=? WHERE id=?");$stmt->execute([$status,filter_var($_POST['id']??0,FILTER_VALIDATE_INT)?:0]);}go('/admin.php#orders');}}
$categories=$pdo->query("SELECT * FROM categories ORDER BY id")->fetchAll();$products=$pdo->query("SELECT * FROM products ORDER BY created_at DESC LIMIT 150")->fetchAll();$orders=$pdo->query("SELECT * FROM orders ORDER BY created_at DESC LIMIT 100")->fetchAll();$counts=['products'=>(int)$pdo->query("SELECT COUNT(*) FROM products")->fetchColumn(),'orders'=>(int)$pdo->query("SELECT COUNT(*) FROM orders")->fetchColumn(),'pending'=>(int)$pdo->query("SELECT COUNT(*) FROM orders WHERE status='pending'")->fetchColumn()];
page_header(t('admin'));?>
<div class="admin"><aside class="admin-nav"><b>NOVA CONTROL</b><a href="/admin.php"><?=h(t('dashboard'))?></a><a href="#products"><?=h(t('manage_products'))?></a><a href="#orders"><?=h(t('manage_orders'))?></a><a href="/index.php"><?=h(t('store'))?></a></aside><section><h1><?=h(t('dashboard'))?></h1><div class="stats"><div class="stat"><?=h(t('products'))?><b><?=$counts['products']?></b></div><div class="stat"><?=h(t('manage_orders'))?><b><?=$counts['orders']?></b></div><div class="stat"><?=h(t('pending'))?><b><?=$counts['pending']?></b></div></div>
<?php if($errors):?><div class="flash"><?=h(implode(' · ',$errors))?></div><?php endif;?><?php if($message=flash()):?><div class="flash"><?=h($message)?></div><?php endif;?>
<div class="panel"><h2><?=h(t('add_product'))?></h2><form method="post" class="stack"><?=csrf_field()?><input type="hidden" name="action" value="add_product"><div class="form-grid"><label><?=h(t('name_ar'))?><input class="field" name="name_ar" maxlength="180" required></label><label><?=h(t('name_fr'))?><input class="field" name="name_fr" maxlength="180" required></label><label><?=h(t('price'))?><input class="field" type="number" name="price" min=".01" step=".01" required></label><label><?=h(t('stock'))?><input class="field" type="number" name="stock" min="0" required></label><label><?=h(t('category'))?><select class="field" name="category"><?php foreach($categories as $c):?><option value="<?=(int)$c['id']?>"><?=h($c['name_ar'])?></option><?php endforeach;?></select></label><label><?=h(t('image'))?><input class="field" type="url" name="image" maxlength="1000"></label><label><?=h(t('desc_ar'))?><textarea class="field" name="desc_ar"></textarea></label><label><?=h(t('desc_fr'))?><textarea class="field" name="desc_fr"></textarea></label></div><button class="btn"><?=h(t('add_product'))?></button></form></div>
<h2 id="products"><?=h(t('manage_products'))?></h2><div class="table-wrap"><table><thead><tr><th><?=h(t('products'))?></th><th><?=h(t('price'))?></th><th><?=h(t('stock'))?></th><th></th></tr></thead><tbody><?php foreach($products as $p):?><tr><td><?=h(product_name($p))?></td><td><?=h(cash($p['price']))?></td><td><?=(int)$p['stock']?></td><td><?php if($p['is_active']):?><form method="post" data-confirm="<?=h(t('delete'))?>?"><?=csrf_field()?><input type="hidden" name="action" value="archive"><input type="hidden" name="id" value="<?=(int)$p['id']?>"><button class="btn danger sm"><?=h(t('delete'))?></button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></div>
<h2 id="orders"><?=h(t('manage_orders'))?></h2><div class="table-wrap"><table><thead><tr><th><?=h(t('order'))?></th><th><?=h(t('customer'))?></th><th><?=h(t('phone'))?></th><th><?=h(t('total'))?></th><th><?=h(t('status'))?></th></tr></thead><tbody><?php foreach($orders as $o):?><tr><td><?=h($o['order_number'])?><br><small><?=h($o['created_at'])?></small></td><td><?=h($o['customer_name'])?> · <?=h($o['city'])?></td><td><?=h($o['phone'])?></td><td><?=h(cash($o['total_amount']))?></td><td><form method="post" class="stack"><?=csrf_field()?><input type="hidden" name="action" value="status"><input type="hidden" name="id" value="<?=(int)$o['id']?>"><select class="field" name="status"><?php foreach($statuses as $st):?><option value="<?=h($st)?>" <?=$o['status']===$st?'selected':''?>><?=h(t($st))?></option><?php endforeach;?></select><button class="btn sm"><?=h(t('save'))?></button></form></td></tr><?php endforeach;?></tbody></table></div></section></div>
<?php page_footer();?>
